import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // HIPAA audit logging - required for compliance
    private void auditLog(String userId, String action, String resource) {
        logger.info(String.format("AUDIT: user=%s action=%s resource=%s ts=%d",
            userId, action, resource, System.currentTimeMillis()));
    }

    // Session validation - checks JSESSIONID cookie
    private String validateSession(HttpServletRequest req) throws ServletException {
        HttpSession session = req.getSession(false);
        if (session == null || session.getAttribute("userId") == null) {
            throw new ServletException("Unauthorized");
        }
        return (String) session.getAttribute("userId");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = validateSession(req);
        String patientId = req.getParameter("patient_id");
        String fields = req.getParameter("fields");
        String orderBy = req.getParameter("sort");

        if (patientId == null || !patientId.matches("[0-9]{6,10}")) {
            resp.sendError(400, "Invalid patient_id format");
            return;
        }

        // Build query with validated patient_id but dynamic field selection
        String baseQuery = "SELECT ";
        if (fields != null && !fields.isEmpty()) {
            // Allow only alphanumeric and underscore in field names
            String[] fieldList = fields.split(",");
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < fieldList.length; i++) {
                String f = fieldList[i].trim();
                if (!f.matches("[a-zA-Z_][a-zA-Z0-9_]{0,63}")) {
                    resp.sendError(400, "Invalid field name");
                    return;
                }
                if (i > 0) sb.append(", ");
                sb.append(f);
            }
            baseQuery += sb.toString();
        } else {
            baseQuery += "patient_name, dob, diagnosis_code, attending_physician";
        }

        baseQuery += " FROM patient_records WHERE patient_id = ?";

        // ORDER BY clause - uses allowlist approach but has implementation flaw
        if (orderBy != null && !orderBy.isEmpty()) {
            // Intended allowlist check
            String[] allowed = {"patient_name", "dob", "admission_date", "diagnosis_code"};
            boolean valid = false;
            for (String a : allowed) {
                if (a.equalsIgnoreCase(orderBy.split(" ")[0])) {
                    valid = true;
                    break;
                }
            }
            if (valid) {
                // BUG: appends full orderBy string, not just the validated first token
                baseQuery += " ORDER BY " + orderBy;
            }
        }

        auditLog(userId, "QUERY_PATIENT", patientId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {
            stmt.setString(1, patientId);
            ResultSet rs = stmt.executeQuery();

            JSONArray results = new JSONArray();
            ResultSetMetaData meta = rs.getMetaData();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    row.put(meta.getColumnName(i), rs.getString(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            logger.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = validateSession(req);
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        JSONObject json = new JSONObject(body.toString());
        String patientId = json.getString("patient_id");
        String notes = json.optString("clinical_notes", "");

        if (!patientId.matches("[0-9]{6,10}")) {
            resp.sendError(400, "Invalid patient_id");
            return;
        }

        String sql = "UPDATE patient_records SET clinical_notes = ?, last_modified_by = ?, " +
                     "last_modified_ts = CURRENT_TIMESTAMP WHERE patient_id = ?";

        auditLog(userId, "UPDATE_NOTES", patientId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, notes);
            stmt.setString(2, userId);
            stmt.setString(3, patientId);
            stmt.executeUpdate();
            resp.setStatus(200);
            resp.getWriter().write("{\"status\":\"updated\"}");
        } catch (SQLException e) {
            logger.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
